"""Handwritten array and vector contracts, checked against complete definitions."""


def section(title, *paragraphs, rows=None, columns=None, bullets=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if rows is not None:
        result["table"] = {"columns": columns or ["Member", "Description"], "rows": rows}
    if bullets:
        result["bullets"] = bullets
    return result


def members(category, memory, immutable=False, contiguous=False, synonyms=True, iterator=True):
    rows = [
        ["`category_type`", f"`{category}_tag`; identifies the container family."],
        ["`mutability_type`", "`immutable_tag`." if immutable else "`mutable_tag`."],
        ["`memory_type`", f"`{memory}_tag`; describes the location of the element storage."],
        ["`size_type`", "`usize`; the unsigned type used for element counts and indices."],
        ["`value_type`", "`T`; the element type."],
        ["`reference`, `ref`" if synonyms else "`reference`", "`T&`."],
        ["`const_reference`, `const_ref`" if synonyms else "`const_reference`", "`const T&`."],
        ["`pointer`", "`T*`."],
        ["`const_pointer`", "`const T*`."],
    ]
    if iterator:
        rows += [["`iterator`", "`T*`; a pointer into contiguous element storage."],
                 ["`const_iterator`", "`const T*`; a pointer into const element storage."]]
    if contiguous:
        rows.append(["`contiguous_tag`", "`void`; marks contiguous element storage."])
    return section("Member types", rows=rows)


